-- DefiMap: 500 source-backed USDA FoodData Central nutrient measurements.
-- Run scientific_datasets_migration.sql first. Matching rows are unchanged; conflicting rows cause an error.
START TRANSACTION;
ON DUPLICATE KEY UPDATE food_record_id = IF(food_nutrient_data.fdc_id <=> VALUES(fdc_id) AND food_nutrient_data.food_name <=> VALUES(food_name) AND food_nutrient_data.nutrient_name <=> VALUES(nutrient_name) AND food_nutrient_data.nutrient_amount <=> VALUES(nutrient_amount) AND food_nutrient_data.nutrient_unit <=> VALUES(nutrient_unit) AND food_nutrient_data.serving_basis <=> VALUES(serving_basis) AND food_nutrient_data.source_url <=> VALUES(source_url) AND food_nutrient_data.verification_status <=> VALUES(verification_status), food_nutrient_data.food_record_id, NULL);
COMMIT;
